minimalist_cover.css:
.min-cover {
  position: relative;
  height: 812px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: var(--color-primary);
  overflow: hidden;
}
.min-cover__bg {
  position: absolute;
  inset: 0;
}
.min-cover__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  filter: brightness(0.5);
}
.min-cover__overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
}
.min-cover__content {
  position: relative;
  z-index: 10;
  color: var(--color-background);
  padding: 2rem;
}
.min-cover__title {
  font-family: var(--font-title);
  font-size: 3.5rem;
  font-weight: 300;
  margin-bottom: 1rem;
  line-height: 1.1;
}
.min-cover__subtitle {
  font-family: var(--font-body);
  font-size: 0.95rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  opacity: 0.8;
  margin-bottom: 2.5rem;
}
.min-cover__btn {
  background: transparent;
  border: 1px solid var(--color-accent);
  color: var(--color-accent);
  padding: 0.8rem 2rem;
  font-family: var(--font-body);
  font-size: 0.9rem;
  cursor: pointer;
  transition: all 0.3s;
}
.min-cover__btn:hover {
  background: var(--color-accent);
  color: var(--color-primary);
}

minimalist_cover.js:
(function() {
  var btn = document.querySelector('.min-cover__btn');
  if(btn) {
    btn.addEventListener('click', function() {
      window.__memoriaGoTo && window.__memoriaGoTo('main');
    });
  }
})();

minimalist_hero.css:
.min-hero {
  padding: 6rem 2rem;
  background: var(--color-background);
  text-align: center;
}
.min-hero__content {
  max-width: 600px;
  margin: 0 auto;
}
.min-hero__label {
  font-family: var(--font-body);
  font-size: 0.9rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 1.5rem;
}
.min-hero__title {
  font-family: var(--font-title);
  font-size: clamp(2rem, 8vw, 4rem);
  font-weight: 300;
  color: var(--color-primary);
  margin-bottom: 2rem;
  line-height: 1.2;
}
.min-hero__divider {
  width: 60px;
  height: 2px;
  background: var(--color-accent);
  margin: 0 auto;
}

minimalist_couple.css:
.min-couple {
  padding: 5rem 2rem;
  background: var(--color-primary);
  color: var(--color-background);
}
.min-couple__container {
  max-width: 600px;
  margin: 0 auto;
}
.min-couple__title {
  font-family: var(--font-title);
  font-size: 2rem;
  font-weight: 300;
  text-align: center;
  margin-bottom: 3rem;
}
.min-couple__grid {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3rem;
  flex-wrap: wrap;
}
.min-couple__person {
  flex: 1;
  min-width: 140px;
  text-align: center;
}
.min-couple__photo-frame {
  width: 160px;
  height: 160px;
  margin: 0 auto 1.5rem;
  border: 1px solid var(--color-accent);
  border-radius: 8px;
  overflow: hidden;
  background: #2a2a2a;
}
.min-couple__photo {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.min-couple__name {
  font-family: var(--font-title);
  font-size: 1.3rem;
  font-weight: 400;
  margin-bottom: 0.5rem;
}
.min-couple__role {
  font-family: var(--font-body);
  font-size: 0.8rem;
  color: var(--color-accent);
  letter-spacing: 0.15em;
  text-transform: uppercase;
}
.min-couple__divider-v {
  width: 1px;
  height: 120px;
  background: rgba(255, 255, 255, 0.15);
  flex-shrink: 0;
}

minimalist_details.css:
.min-details {
  padding: 5rem 2rem;
  background: var(--color-background);
}
.min-details__container {
  max-width: 700px;
  margin: 0 auto;
}
.min-details__title {
  font-family: var(--font-title);
  font-size: 2rem;
  font-weight: 300;
  text-align: center;
  color: var(--color-primary);
  margin-bottom: 3rem;
}
.min-details__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
}
.min-details__item {
  text-align: center;
  padding: 2rem;
  border: 1px solid #e0e0e0;
  border-radius: 8px;
}
.min-details__label {
  font-family: var(--font-body);
  font-size: 0.9rem;
  color: var(--color-accent);
  margin-bottom: 0.8rem;
}
.min-details__value {
  font-family: var(--font-title);
  font-size: 1.2rem;
  font-weight: 400;
  color: var(--color-primary);
  margin-bottom: 0.5rem;
}
.min-details__address {
  font-family: var(--font-body);
  font-size: 0.85rem;
  color: #666;
  line-height: 1.5;
}
